import { test, expect } from '@playwright/test';

test.describe('Date Picker - Past Date Prevention', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should disable past dates in the date picker', async ({ page }) => {
    // Open the date picker
    const datePickerButton = page.getByRole('button', { name: /select date/i });
    await datePickerButton.click();

    // Get today's date
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    // Format dates for comparison
    const yesterdayFormatted = yesterday.toISOString().split('T')[0];
    const todayFormatted = today.toISOString().split('T')[0];

    // Check that yesterday's date is disabled
    const yesterdayButton = page.getByRole('button', {
      name: new RegExp(`^${yesterday.getDate()}$`)
    });

    // Verify past date button is disabled or has disabled attribute
    const isDisabled = await yesterdayButton.evaluate((el: HTMLElement) => {
      return el.hasAttribute('disabled') || 
             el.getAttribute('aria-disabled') === 'true' ||
             el.classList.contains('disabled');
    });

    expect(isDisabled).toBe(true);

    // Verify today's date is enabled
    const todayButton = page.getByRole('button', {
      name: new RegExp(`^${today.getDate()}$`)
    });

    const todayIsEnabled = await todayButton.evaluate((el: HTMLElement) => {
      return !el.hasAttribute('disabled') && 
             el.getAttribute('aria-disabled') !== 'true' &&
             !el.classList.contains('disabled');
    });

    expect(todayIsEnabled).toBe(true);
  });

  test('should allow selecting future dates', async ({ page }) => {
    // Open the date picker
    const datePickerButton = page.getByRole('button', { name: /select date/i });
    await datePickerButton.click();

    // Get a future date (7 days from now)
    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + 7);

    // Click on the future date
    const futureDateButton = page.getByRole('button', {
      name: new RegExp(`^${futureDate.getDate()}$`)
    });

    // Verify the button is enabled
    const isEnabled = await futureDateButton.evaluate((el: HTMLElement) => {
      return !el.hasAttribute('disabled') && 
             el.getAttribute('aria-disabled') !== 'true' &&
             !el.classList.contains('disabled');
    });

    expect(isEnabled).toBe(true);

    // Click the future date
    await futureDateButton.click();

    // Verify the date was selected
    const dateInput = page.getByLabel(/booking date/i);
    const selectedValue = await dateInput.inputValue();

    expect(selectedValue).toContain(futureDate.getDate().toString());
  });

  test('should show error message when attempting to select past date', async ({ page }) => {
    // Try to interact with a past date input
    const dateInput = page.getByLabel(/booking date/i);

    // Get yesterday's date
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayFormatted = yesterday.toISOString().split('T')[0];

    // Attempt to set past date directly
    await dateInput.fill(yesterdayFormatted);

    // Trigger validation
    await dateInput.blur();

    // Check for error message
    const errorMessage = page.getByText(/cannot select past dates|date must be in the future|invalid date selection/i);

    await expect(errorMessage).toBeVisible();
  });

  test('should prevent form submission with past date', async ({ page }) => {
    // Get yesterday's date
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayFormatted = yesterday.toISOString().split('T')[0];

    // Fill the date input with past date
    const dateInput = page.getByLabel(/booking date/i);
    await dateInput.fill(yesterdayFormatted);

    // Try to submit the form
    const submitButton = page.getByRole('button', { name: /submit|book|confirm/i });
    await submitButton.click();

    // Verify form was not submitted (error message should appear)
    const errorMessage = page.getByText(/cannot select past dates|date must be in the future|invalid date selection/i);
    await expect(errorMessage).toBeVisible();

    // Verify we're still on the same page
    expect(page.url()).toContain('localhost');
  });

  test('should correctly handle month transitions for past dates', async ({ page }) => {
    // Open the date picker
    const datePickerButton = page.getByRole('button', { name: /select date/i });
    await datePickerButton.click();

    // Navigate to previous month if available
    const prevMonthButton = page.getByRole('button', { name: /previous|prev|</ }).first();

    // Check if previous month button exists and is enabled
    const prevMonthExists = await prevMonthButton.isVisible().catch(() => false);

    if (prevMonthExists) {
      // Click previous month
      await prevMonthButton.click();

      // All dates in previous month should be disabled
      const dateButtons = page.getByRole('button').filter({
        has: page.locator('[aria-label*="previous month"]')
      });

      const count = await dateButtons.count();

      // Verify that dates from previous month are disabled
      if (count > 0) {
        for (let i = 0; i < Math.min(count, 5); i++) {
          const button = dateButtons.nth(i);
          const isDisabled = await button.evaluate((el: HTMLElement) => {
            return el.hasAttribute('disabled') || 
                   el.getAttribute('aria-disabled') === 'true' ||
                   el.classList.contains('disabled');
          }).catch(() => false);

          if (isDisabled !== undefined) {
            expect(isDisabled).toBe(true);
          }
        }
      }
    }
  });

  test('should maintain date picker state across interactions', async ({ page }) => {
    // Open the date picker
    const datePickerButton = page.getByRole('button', { name: /select date/i });
    await datePickerButton.click();

    // Verify date picker is visible
    const datePicker = page.getByRole('dialog', { name: /date picker|select date/i });
    await expect(datePicker).toBeVisible();

    // Get today's date
    const today = new Date();
    const todayButton = page.getByRole('button', {
      name: new RegExp(`^${today.getDate()}$`)
    });

    // Verify today's date is still enabled
    const isEnabled = await todayButton.evaluate((el: HTMLElement) => {
      return !el.hasAttribute('disabled') && 
             el.getAttribute('aria-disabled') !== 'true' &&
             !el.classList.contains('disabled');
    });

    expect(isEnabled).toBe(true);

    // Close and reopen the date picker
    await page.keyboard.press('Escape');
    await datePickerButton.click();

    // Verify the same state is maintained
    await expect(datePicker).toBeVisible();

    const isStillEnabled = await todayButton.evaluate((el: HTMLElement) => {
      return !el.hasAttribute('disabled') && 
             el.getAttribute('aria-disabled') !== 'true' &&
             !el.classList.contains('disabled');
    });

    expect(isStillEnabled).toBe(true);
  });
});
